// src/parser.xi
pub fn tokenize(input: Str) -> Vec<Str> {
    return internal_split(input)
}

fn internal_split(input: Str) -> Vec<Str> {
    let mut result = Vec::new()
    for word in input.split(' ') {
        result.push(word)
    }
    return result
}

#[cfg(test)]
mod tests {
    use super::*;

    @test
    fn test_internal_split() {
        let tokens = internal_split("hello world")
        assert_eq(tokens.len(), 2)
    }
}

// tests/parser_test.xi
use my_crate::parser::tokenize;

@test
fn test_tokenize_public_api() {
    let tokens = tokenize("a b c")
    assert_eq(tokens.len(), 3)
    assert_eq(tokens[0], "a")
    assert_eq(tokens[2], "c")
}
